#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 2;
    size_t count = 0;
    int* buffer = (int*)malloc(cap * sizeof(int));
    if (!buffer) return 1;

    for (int val = 10; val <= 60; val += 10) {
        if (count >= cap) {
            cap *= 2;
            int* next = (int*)realloc(buffer, cap * sizeof(int));
            if (!next) {
                free(buffer);
                return 1;
            }
            buffer = next;
        }
        buffer[count++] = val;
    }

    printf("Dynamic buffer (capacity %zu, count %zu):
", cap, count);
    for (size_t i = 0; i < count; i++) {
        printf("%d ", buffer[i]);
    }
