#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdbool.h>

typedef struct FileStats {
    long lines;
    long words;
    long bytes;
} FileStats;

int analyze_file(const char* filepath, FileStats* stats) {
    FILE* f = fopen(filepath, "r");
    if (!f) return 0;

    stats->lines = 0;
    stats->words = 0;
    stats->bytes = 0;

    int c;
    bool in_word = false;
    while ((c = fgetc(f)) != EOF) {
        stats->bytes++;
        if (c == '
') stats->lines++;
        if (isspace(c)) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            stats->words++;
        }
    }
    fclose(f);
    return 1;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file1> [file2 ...]
", argv[0]);
        return 1;
    }

    printf("%-20s %8s %8s %8s
", "File", "Lines", "Words", "Bytes");
    printf("--------------------------------------------------
");

    for (int i = 1; i < argc; i++) {
        FileStats stats;
        if (analyze_file(argv[i], &stats)) {
            printf("%-20s %8ld %8ld %8ld
", argv[i], stats.lines, stats.words, stats.bytes);
        } else {
            printf("%-20s [ERROR: cannot open file]
", argv[i]);
        }
    }
    return 0;
}

