#include <stdio.h>
#include <stdlib.h>

typedef struct Matrix {
    int rows;
    int cols;
    double** data;
} Matrix;

Matrix* matrix_create(int rows, int cols) {
    Matrix* m = (Matrix*)malloc(sizeof(Matrix));
    if (!m) return NULL;
    m->rows = rows;
    m->cols = cols;
    m->data = (double**)malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; i++) {
        m->data[i] = (double*)calloc(cols, sizeof(double));
    }
    return m;
}

void matrix_free(Matrix* m) {
    if (!m) return;
    for (int i = 0; i < m->rows; i++) {
        free(m->data[i]);
    }
    free(m->data);
    free(m);
}

Matrix* matrix_multiply(const Matrix* a, const Matrix* b) {
    if (a->cols != b->rows) return NULL;
    Matrix* res = matrix_create(a->rows, b->cols);
    for (int i = 0; i < a->rows; i++) {
        for (int j = 0; j < b->cols; j++) {
            double sum = 0.0;
            for (int k = 0; k < a->cols; k++) {
                sum += a->data[i][k] * b->data[k][j];
            }
            res->data[i][j] = sum;
        }
    }
    return res;
}

void matrix_print(const Matrix* m, const char* label) {
    printf("Matrix %s (%dx%d):
", label, m->rows, m->cols);
    for (int i = 0; i < m->rows; i++) {
        printf("  [ ");
        for (int j = 0; j < m->cols; j++) {
            printf("%6.1f ", m->data[i][j]);
        }
        printf("]
");
    }
}

int main(void) {
    Matrix* a = matrix_create(2, 2);
    a->data[0][0] = 1.0; a->data[0][1] = 2.0;
    a->data[1][0] = 3.0; a->data[1][1] = 4.0;

    Matrix* b = matrix_create(2, 2);
    b->data[0][0] = 2.0; b->data[0][1] = 0.0;
    b->data[1][0] = 1.0; b->data[1][1] = 2.0;

    Matrix* c = matrix_multiply(a, b);

    matrix_print(a, "A");
    matrix_print(b, "B");
    matrix_print(c, "C = A * B");

    matrix_free(a);
    matrix_free(b);
    matrix_free(c);
    return 0;
}

